// =============================================================================
// RANKING TIDSSERIE - Kommunranking över tid för stapeldiagram-animation
// =============================================================================
rankingTimeSeries = {
  const kommuner = [
    { namn: "Halmstad", start: 65, end: 78 },
    { namn: "Varberg", start: 55, end: 72 },
    { namn: "Kungsbacka", start: 70, end: 85 },
    { namn: "Falkenberg", start: 58, end: 68 },
    { namn: "Laholm", start: 52, end: 62 },
    { namn: "Hylte", start: 48, end: 55 }
  ];

  const years = d3.range(2010, 2025);
  const data = [];

  kommuner.forEach(k =&gt; {
    years.forEach((år, i) =&gt; {
      const progress = i / (years.length - 1);
      // Varierande tillväxt med lite brus
      const noise = Math.sin(år * 0.3 + k.namn.length * 2) * 4;
      const value = k.start + (k.end - k.start) * progress + noise;

      data.push({
        kommun: k.namn,
        index: Math.round(value * 10) / 10,
        år: år
      });
    });
  });

  return data;
}

// =============================================================================
// BEFOLKNINGSUTVECKLING - Indexerad data 2000-2024 (index 100 = år 2000)
// Syntetisk data baserad på verkliga trender för Sveriges 21 regioner + Riket
// =============================================================================

befolkningIndex = {
  // Tillväxttrender per region (slutvärde år 2024, index 100 = år 2000)
  const regionTrends = {
    "Stockholm": 128,      // Stark tillväxt
    "Uppsala": 124,        // Stark tillväxt
    "Skåne": 122,          // Stark tillväxt
    "Halland": 121,        // Stark tillväxt
    "Västra Götaland": 115,// God tillväxt
    "Östergötland": 111,   // Måttlig tillväxt
    "Jönköping": 109,      // Måttlig tillväxt
    "Kronoberg": 108,      // Måttlig tillväxt
    "Södermanland": 108,   // Måttlig tillväxt
    "Örebro": 107,         // Måttlig tillväxt
    "Västmanland": 106,    // Svag tillväxt
    "Gotland": 104,        // Nästan oförändrad
    "Västerbotten": 103,   // Nästan oförändrad
    "Kalmar": 99,          // Svag nedgång
    "Blekinge": 98,        // Nedgång
    "Jämtland": 97,        // Nedgång
    "Värmland": 96,        // Nedgång
    "Dalarna": 95,         // Nedgång
    "Gävleborg": 94,       // Nedgång
    "Norrbotten": 93,      // Nedgång
    "Västernorrland": 91,  // Stark nedgång
    "Riket": 118           // Nationellt genomsnitt
  };

  // Generera årlig data 2000-2024 med realistisk kurva
  const years = d3.range(2000, 2025);
  const data = [];

  for (const [region, endValue] of Object.entries(regionTrends)) {
    const growthRate = (endValue - 100) / 24;  // Linjär bas

    years.forEach((year, i) =&gt; {
      // Lägg till lite variation och S-kurva
      const progress = i / 24;
      const sCurve = progress &lt; 0.5
        ? 2 * progress * progress
        : 1 - Math.pow(-2 * progress + 2, 2) / 2;

      // Kombination av linjär och S-kurva med lite brus
      const noise = (Math.sin(year * 0.7 + region.length) * 0.5);
      const value = 100 + (endValue - 100) * (0.7 * progress + 0.3 * sCurve) + noise;

      data.push({
        år: year,
        index: Math.round(value * 10) / 10,
        region: region
      });
    });
  }

  return data;
}

// =============================================================================
// KOMMUNDATA - Riktig SCB-data (290 kommuner + Sverige-snitt)
// =============================================================================
beeswarmKommuner = FileAttachment("data/processed/03-beeswarm-kommuner.json").json()

Halland: en flerkärnig och tät region
Halland är en av Sveriges 21 regioner och sträcker sig längs västkusten mellan Göteborg i norr och nordvästra Skåne i söder. Med drygt 345 000 invånare (2024) utgör länet knappt 3,3 procent av landets befolkning, fördelad på en landareal om cirka 5 450 kvadratkilometer, motsvarande 1,3 procent av Sveriges yta. Proportionerna säger något om regionens karaktär: Halland rymmer en förhållandevis stor andel av befolkningen på en liten del av landytan, i ett land som ur ett europeiskt perspektiv tillhör de allra största men också de mest glesbefolkade, med i genomsnitt knappt 26 invånare per kvadratkilometer.
Karta 1: Kommuner, tätorter och infrastruktur i Sydsverige

karta(geoSydsverige, {
  title: "Sydsverige: kommuner, tätorter och infrastruktur",
  subtitle: "Halland i sitt regionala sammanhang",
  caption: "Källa: SCB tätorter 2023, befolkning 2024. Trafikverket FPV 2026.",
  highlight: ["Halmstad", "Varberg", "Kungsbacka", "Falkenberg", "Laholm", "Hylte"],
  zoomTo: true,
  zoomPadding: 1.5,
  urbanAreas: "tatorter",
  roads: "vagnat",
  railways: "jarnvag",
  urbanMinPop: 2000,
  logo: "logo_farg.svg",
  info: `&lt;p&gt;&lt;strong&gt;Om vägnätet (FPV)&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Vägnätet i kartan bygger på Trafikverkets &lt;em&gt;funktionellt prioriterade vägnät&lt;/em&gt; (FPV), en klassificering som rangordnar vägar utifrån deras transportfunktion snarare än trafikvolym. Syftet är att ge en enhetlig grund för planering, underhåll och investeringar i vägsystemet.&lt;/p&gt;
&lt;p&gt;FPV delar in vägarna i tre kategorier:&lt;/p&gt;
&lt;ul style="margin:0.3em 0 0.8em 1.2em;padding:0;font-size:inherit"&gt;
&lt;li&gt;&lt;strong&gt;Nationella vägar&lt;/strong&gt; binder samman landets större regioner och har en central funktion för långväga gods- och persontransporter. I Halland utgörs dessa främst av E6 och riksväg 25/26.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Regionalt viktiga vägar&lt;/strong&gt; knyter samman kommunhuvudorter med varandra och med det nationella vägnätet, exempelvis väg 15, 41 och 153/154.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Kompletterande regionalt viktiga vägar&lt;/strong&gt; kompletterar det regionala nätet och säkerställer tillgänglighet till mindre orter och landsbygdsområden.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Om tätortsavgränsningen&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;SCB avgränsar tätorter utifrån sammanhängande bebyggelse: minst 200 invånare och normalt högst 200 meter mellan byggnader. För större orter tillåts avståndet stegvis öka upp till 500 meter via vägnätet. Avgränsningen är rent statistisk och följer bebyggelsens utbredning, inte administrativa gränser.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Kungsbacka (GBG)&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;I takt med att bebyggelsen förtätats längs kusten mellan Göteborg och Kungsbacka har flera orter i Kungsbacka kommun successivt vuxit samman med Göteborgs tätort. Anneberg uppgick vid SCB:s uppdatering 2015; Billdal med Kullavik, Särö och Brattås följde 2018. Vid uppdateringen 2020 hade även centrala Kungsbacka vuxit samman med Göteborg.&lt;/p&gt;
&lt;p&gt;Göteborgs tätort sträcker sig därmed över länsgränsen in i Halland. I denna karta har vi klippt tätortspolygonen mot länsgränsen och benämner Hallandsdelen &lt;em&gt;Kungsbacka (GBG)&lt;/em&gt;. Befolkningstalet (39 913) avser de invånare inom Göteborgs tätort som är folkbokförda i Hallands län.&lt;/p&gt;`
})






Halland är med sina drygt 5 450 kvadratkilometer ett av landets minsta län, det fjärde minsta efter Blekinge, Gotland och Västmanland. Befolkningsmässigt placerar sig regionen som sjunde störst bland de 21 länen. Framför allt är det befolkningstätheten som utmärker Halland: med drygt 63 invånare per kvadratkilometer är länet det fjärde tätaste i landet, efter Stockholm, Skåne och Västra Götaland, och mer än dubbelt så tättbefolkat som riket i genomsnitt. Sedan millennieskiftet har tätheten ökat med omkring 26 procent, en utveckling som speglar den starka befolkningstillväxt som präglar hela Sydvästsverige.
Hallands geografiska läge är en av regionens mest framträdande tillgångar. Länet utgör en del av den svenska västkusten, och E6:an och Västkustbanan löper genom hela regionen och knyter samman de halländska tätorterna med Göteborg i norr och Ängelholm, Helsingborg, Malmö och i förlängningen Köpenhamn i söder. Österut ger riksvägarna 25, 26 och 41 tvärgående kopplingar mot Småland och Västra Götaland. Halland ingår därmed i ett sammanhängande pendlings- och arbetsmarknadsområde som sträcker sig genom hela sydvästra Sverige och vidare in i Öresundsregionen. Kombinationen av kustläge, storstadsnärhet och väl utbyggd infrastruktur ger regionen i allt väsentligt mycket goda ekonomiskgeografiska förutsättningar.
Ortsstrukturer och befolkningskoncentrationer studeras mer i detalj i nästa avsnitt, men redan här kan man konstatera att Halland har flera tätorter med betydande befolkningsunderlag. Tre av kommunhuvudorterna, Halmstad (73 000 invånare i tätorten), Varberg (39 000) och Falkenberg (30 000), har var för sig en storlek som i den regionalekonomiska litteraturen brukar betraktas som tillräcklig för att generera agglomerationsfördelar: en bredare lokal arbetsmarknad, ett mer differentierat serviceutbud och bättre förutsättningar för kunskapsspridning. Därtill kommer de knappt 40 000 Hallandsinvånare som sedan tätortsuppdateringen 2020 statistiskt ingår i Göteborgs tätort, huvudsakligen i Kungsbacka kommun. Det samlade befolkningsunderlaget, den marknad som invånare, företag och institutioner har tillgång till, överstiger med god marginal vad de enskilda orterna kan erbjuda var för sig. Forskningen visar dock att en flerkärnig ortsstruktur inte automatiskt levererar samma fördelar som en enda stor stad; det förutsätter funktionell integration i form av pendling, arbetsmarknadsutbyte och komplementär specialisering mellan orterna. Hur Hallands orter förhåller sig till varandra i denna mening, och vilka koncentrationsmönster som präglar regionen, är temat för det följande avsnittet.

Befolkningsfördelning och koncentration
Hallands drygt 345 000 invånare gör regionen till den sjunde folkrikaste av landets 21 län. Befolkningen är fördelad på sex kommuner, vilket är det lägsta antalet efter Gotlands enda. Halmstad är störst med drygt 106 000 invånare, följt av Kungsbacka (86 000), Varberg (69 000), Falkenberg (47 000), Laholm (27 000) och Hylte (10 000). Riksmedianen för Sveriges 290 kommuner ligger vid knappt 19 500 invånare. Fyra av Hallands sex kommuner överstiger det värdet; Halmstad placerar sig som landets 25:e folkrikaste kommun och Kungsbacka som den 50:e. Halland är med andra ord en region med få men förhållandevis stora kommuner. Fördelningen mellan dem är dessutom jämnare än i många andra län: ingen enskild kommun dominerar på samma sätt som Uppsala dominerar Uppsala län eller Umeå dominerar Västerbotten.
